def get_name_in_module(module: str, qualname: str, attr_getter: Optional[
    Callable[[Any, str], Any]]=None) ->Any:
    """Return the object specified by qualname in module.

    Raises:
        NameLookupError if we can't find the named object
    """
    try:
        mod = importlib.import_module(module)
    except ImportError:
        raise NameLookupError(f"Could not import module {module}")

    obj = mod
    for attr in qualname.split("."):
        try:
            if attr_getter is not None:
                obj = attr_getter(obj, attr)
            else:
                obj = getattr(obj, attr)
        except AttributeError:
            raise NameLookupError(
                f"Could not find {attr!r} in {obj!r} ({module}.{qualname})"
            )
    return obj
